DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `product_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `description` longtext,
  `price` decimal(12,2) NOT NULL,
  `original_price` decimal(12,2) DEFAULT NULL,
  `discount` decimal(5,2) DEFAULT NULL,
  `stock` int NOT NULL,
  `image` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `is_deal_of_the_day` tinyint(1) NOT NULL,
  `is_featured` tinyint(1) NOT NULL,
  `is_new` tinyint(1) NOT NULL,
  `category_id` int DEFAULT NULL,
  `abroad_delivery_days` int unsigned DEFAULT NULL,
  `is_abroad_order` tinyint(1) NOT NULL,
  `slug` varchar(191) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`product_id`),
  KEY `products_category_id_a7a3a156_fk_categories_category_id` (`category_id`),
  KEY `products_slug_8f20884e` (`slug`),
  CONSTRAINT `products_category_id_a7a3a156_fk_categories_category_id` FOREIGN KEY (`category_id`) REFERENCES `categories` (`category_id`),
  CONSTRAINT `products_chk_1` CHECK ((`abroad_delivery_days` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

