INSERT INTO `products` VALUES (1,'Apple AirTag 4 Pack','Keep track of and find your items alongside friends and devices in the Find My app\r\nSimple one-tap setup instantly connects AirTag with your iPhone or iPad\r\nPlay a sound on the built-in speaker to help find your things, or just ask Siri for help\r\nPrecision Finding with Ultra Wideband technology leads you right to your nearby AirTag (on select iPhone models)\r\nFind items further away with the help of hundreds of millions of Apple devices in the Find My network\r\nPut AirTag into Lost Mode to be automatically notified when it’s detected in the Find My network\r\nAll communication with the Find My network is anonymous and encrypted for privacy, Location data and history are never stored on AirTag',180000.00,NULL,NULL,3,'media/products/71gY9EcTaS._AC_SL1500__epmmk0','2025-08-28 16:03:35.000000',0,0,0,1,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(2,'PlayStation®5 console (slim)','PlayStation®5 console (slim)',1000000.00,NULL,NULL,2,'media/products/ps5_slim1_f6kiwx','2025-08-30 08:41:28.281385',0,0,0,9,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(3,'PlayStation DualSense® Wireless Controller - White','PlayStation DualSense® Wireless Controller - White',100000.00,NULL,NULL,3,'media/products/ps5_pad1_ic5egm','2025-08-30 08:45:32.313161',0,0,0,9,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(4,'Sony PS5 PlayStation 5','Sony PS5 PlayStation 5 Digital Edition Gaming Console + Wireless Controller - 16GB GDDR6 RAM, 825GB SSD, 120Hz 8K Output, White',800000.00,NULL,NULL,2,'media/products/ps5_fat1_r0sbyc','2025-08-30 08:50:34.495186',0,0,0,9,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(5,'Sony PlayStation 5 Pro','The PlayStation 5 Pro (PS5 Pro) is Sony\'s most advanced gaming console, delivering unparalleled performance and visual fidelity. Equipped with a powerful GPU featuring 67% more compute units and 28% faster memory than the base PS5, it offers up to 45% faster rendering for smoother gameplay.',1500000.00,NULL,NULL,2,'media/products/ps5_pro1_zxuaxs','2025-08-30 08:58:16.135483',0,0,0,9,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(6,'Playstation 4 Pro','Playstation 4 Pro 2TB SSD Console with Dualshock 4 Wireless Controller Bundle, 4K HDR, Playstation Pro Enhanced with Fast Solid State Drive',550000.00,NULL,NULL,2,'media/products/ps4_pro3_wfpizb','2025-08-30 09:02:59.760639',0,0,0,NULL,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(7,'PS4 Slim','PS4 Slim 500GB Console + Controller',450000.00,500000.00,10.00,2,'media/products/ps4_slim1_gzy8zz','2025-08-30 09:12:06.737334',1,0,0,9,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(8,'DualShock 4 Wireless Controller','DualShock 4 Wireless Controller for PlayStation 4 - Jet Black',90000.00,NULL,NULL,3,'media/products/controller3_ols9ro','2025-08-30 09:17:53.039294',0,0,0,9,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(9,'Apple Pencil (2nd Generation)','Apple Pencil (2nd Generation): Device Compatibility Check Required - Pixel-Perfect Precision, Perfect for Note-Taking, Drawing, and Signing documents. Attaches, Charges, and Pairs magnetically.',200000.00,NULL,NULL,3,'media/products/apple_pencil2_a8jngz','2025-08-30 09:22:24.196180',0,0,0,1,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(10,'AirPods Pro 2 (2024 Model)','Pro-level Active Noise Cancellation. Footnote Now with a clinical-grade Hearing Aid Footnote feature. Footnote',350000.00,NULL,NULL,2,'media/products/61SUj2aKoEL._AC_SL1500__fvx005','2025-08-30 09:30:48.097118',0,0,0,3,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(11,'AirPods 4','',1000.00,NULL,NULL,2,'media/products/airpod_4_1_ditekc','2025-08-30 10:06:25.856694',0,0,0,3,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(12,'Apple AirPods Max','Apple AirPods Max Wireless Over-Ear Headphones, Active Noise Cancelling, Transparency Mode, Personalized Spatial Audio, Dolby Atmos, Bluetooth Headphones for iPhone – Space Gray',650000.00,NULL,NULL,5,'media/products/airpod_max_2_mhkkwp','2025-08-30 10:35:33.984666',0,0,0,3,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(13,'Sony WH-1000XM6','Sony WH-1000XM6 The Best Wireless Noise Canceling Headphones, HD NC Processor QN3, 12 Microphones, Adaptive NC Optimizer, Mastered by Engineers, Studio-Quality, 30-Hour Battery, Black',750000.00,700000.00,7.00,2,'media/products/sony_pods1_ygve3e','2025-08-30 11:11:54.193788',1,0,0,3,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(14,'Apple Pencil (USB-C)','Apple Pencil (USB-C) delivers pixel-perfect precision with low latency and tilt sensitivity, making it ideal for notes, sketches, markups, and more. It pairs and charges via USB-C, attaches magnetically for storage, and supports hover on the latest iPad Pro (M4, 6th/4th gen) and iPad Air (M2).',170000.00,NULL,NULL,6,'media/products/apple_pencil_usbc_1_ejrgm9','2025-08-30 12:32:38.253225',0,0,0,1,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(15,'Apple Pencil (1st generation)','Apple Pencil (1st generation) brings pixel-perfect precision with pressure and tilt sensitivity for natural drawing, shading, and note-taking, pairing and charging easily via Lightning.',180000.00,NULL,NULL,4,'media/products/apple_pencil_first_gen_1_nrpnaj','2025-08-30 12:38:15.911659',0,0,0,1,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(16,'Apple Pencil Pro','Apple Pencil Pro enhances creativity with squeeze and double-tap controls, barrel roll rotation, haptic feedback, and Apple Pencil hover for pixel-perfect precision. It attaches, pairs, and charges magnetically on your iPad, and can be easily located via the Find My app.',200000.00,220000.00,9.09,4,'media/products/apple_pencil_pro_1_hlwbww','2025-08-30 13:00:05.416844',1,0,0,1,NULL,0,NULL,'2025-11-28 18:01:28.373293'),(17,'Apple 2022 iPad Pro','Apple 2022 iPad Pro – Powered by the M2 chip, featuring a stunning Liquid Retina XDR display, ProMotion, advanced cameras, Apple Pencil Pro support, and fast Wi-Fi 6E/5G connectivity for a smooth, high-performance experience. Available for 256gb and 512gb',1200000.00,1250000.00,4.00,2,'media/products/ipad_pro_2_skq5l3','2025-08-30 1